use crate::aap::caps::state_read;

struct Node;

/// Keys tried, in order, in the `subscriptions` store.
const KEYS: &[&str] = &["urls", "subscriptions"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let parsed = parse_list(&raw);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }
        SubscriptionList { urls: dedupe(urls) }
    }
}

fn dedupe(items: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(items.len());
    for item in items {
        if !out.iter().any(|u| u == &item) {
            out.push(item);
        }
    }
    out
}

/// Accepts either a JSON array of strings or a newline/comma/whitespace
/// separated list. Blank entries and `#` comment lines are ignored.
fn parse_list(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('[') {
        if let Some(v) = parse_json_string_array(trimmed) {
            return v
                .into_iter()
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect();
        }
    }
    let mut out = Vec::new();
    for line in trimmed.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        for part in line.split(|c: char| c == ',' || c.is_whitespace()) {
            let part = part.trim();
            if !part.is_empty() {
                out.push(part.to_string());
            }
        }
    }
    out
}

/// Minimal parser for a JSON array whose elements are all strings.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.chars().peekable();
    let mut out = Vec::new();

    skip_ws(&mut chars);
    if chars.next()? != '[' {
        return None;
    }
    skip_ws(&mut chars);
    if chars.peek() == Some(&']') {
        chars.next();
        skip_ws(&mut chars);
        return if chars.next().is_none() { Some(out) } else { None };
    }
    loop {
        skip_ws(&mut chars);
        if chars.next()? != '"' {
            return None;
        }
        let mut cur = String::new();
        loop {
            match chars.next()? {
                '"' => break,
                '\\' => match chars.next()? {
                    '"' => cur.push('"'),
                    '\\' => cur.push('\\'),
                    '/' => cur.push('/'),
                    'b' => cur.push('\u{8}'),
                    'f' => cur.push('\u{c}'),
                    'n' => cur.push('\n'),
                    'r' => cur.push('\r'),
                    't' => cur.push('\t'),
                    'u' => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            code = code * 16 + chars.next()?.to_digit(16)?;
                        }
                        cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => return None,
                },
                c => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&mut chars);
        match chars.next()? {
            ',' => continue,
            ']' => break,
            _ => return None,
        }
    }
    skip_ws(&mut chars);
    if chars.next().is_some() {
        return None;
    }
    Some(out)
}

fn skip_ws(chars: &mut std::iter::Peekable<std::str::Chars<'_>>) {
    while let Some(c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
}

export!(Node);
